INSERT INTO team_tactic_setups VALUES(1,'2025-26','FC26','optimal','4-2-3-1 Wide','Short Passing','Balanced',52,NULL,'Emery 25/26: positional short build-up from the back (Martínez + Pau Torres BPD) — Short Passing. Defence is a compact 4-4-2 MID-block with opportunistic ball-winning, not an aggressive press or ultra-high line — Balanced, line ~52 (mid). CORRECTION 2026-07-02: previously High/68 from the 23/24 high-line narrative; 25/26-specific analyses (themastermindsite, totalfootballanalysis) and zero counter-goals-conceded contradict it — see tactic_observations scope=defence. Pairs with player_role_map kind=optimal. [2026-07-02 FORMATION PIN: in-game formation fixed to 4-2-3-1 Wide — left attacking slot is LM (WM type), so analysis-label LW prescriptions map to wm_* in-game equivalents and measured-nearest roles were refit vs wm kernels (see transfer_targets LM rows + player_role_map kind=role:LM).]','FINAL (data-only) — 실측·분석 기반 확정. 게임 내 검증은 수동 플레이 환경이라 생략 (사용자 결정 2026-07-05). 이전 게이트: MEDIUM — team-setting mapping grounded in 25/26 analyses + measured heatmaps, but not yet validated in-game. Validate by building the tactic in FC26, saving tactic_code, comparing in-game vs measured heatmaps.');
INSERT INTO team_tactic_setups VALUES(2,'2025-26','FC26','optimal:rogers10','4-2-3-1 Wide','Short Passing','Balanced',47,NULL,'PERSONNEL VARIANT of kind=optimal for the Rogers-at-No.10 XI (e.g. Baturina/Tavernier LM + Rogers CAM). Two data drivers (2026-07-03 인선-전술 분석, docs/20 규칙 B): (1) front-six normalized defensive share drops 31.0%→28.8% (lowest of all variants) — line lowered 52→47 to compensate; (2) attack flips right (unit lane L 18%→12%, Rogers CAM centroid x=57.5) — LEFT exposure is asymmetric, so pair with LB Attack compensation + RM wm_widemid/Support (rule A-3). Build-up stays Short Passing (deep drop-in creators support it). Counter is a contested/away experiment only.','FINAL (data-only) — 실측·분석 기반 확정. 게임 내 검증은 수동 플레이 환경이라 생략 (사용자 결정 2026-07-05). 이전 게이트: MEDIUM — same in-game-unvalidated caveat as kind=optimal; validate via tactic_code + in-game heatmap comparison.');
INSERT INTO team_tactic_setups VALUES(3,'2025-26','FC26','optimal:vs-strong','4-2-3-1 Wide','Short Passing','Deep',43,NULL,'vs 리버풀·시티급 강팀: 물러나 흡수. 실측 근거 리버풀전 PPDA 20.43, 시티전 14.44 (에메리는 강팀 상대 라인 내려 블록 유지). 문서 FC26_에메리_빌라_전술세팅.md §1 흡수. 빌드업은 base Short Passing 유지(문서는 Balanced 주장 — 미해결, tactic_code 검증 필요). [결과 보강 2026-07-02: 저점유(<=48%) 국면 14승1무2패(+1.00) — 첼시·토트넘 원정, 리버풀·시티·아스널전 포함. 흡수-역습이 팀의 최강 얼굴임을 결과가 확인. tactic_observations scope=possession.]','FINAL (data-only) — 실측·분석 기반 확정. 게임 내 검증은 수동 플레이 환경이라 생략 (사용자 결정 2026-07-05). 이전 게이트: MEDIUM — 게임 미검증, PPDA 실측 기반');
INSERT INTO team_tactic_setups VALUES(4,'2025-26','FC26','optimal:vs-weak','4-2-3-1 Wide','Short Passing','High',67,NULL,'vs 약팀·로우블록: 전방 압박 극대화. 실측 근거 울브스전 PPDA 4.99, 선덜랜드전 5.78. High까지가 상한(Aggressive 미사용 — 에메리는 선택적 압박, 게겐프레싱 아님). 문서 §1 흡수. [결과 보강 2026-07-02: 점유-성적 역상관 실측(r=-0.29, 45경기)이 이 변형의 필요를 결과 축에서 확인 — 고점유(>=55%) 국면 8승3무6패로 표본 내 패배 전부가 여기 몰림(CP H 0-3, 브렌트포드 H/A, 에버턴 H, 고어헤드). 로우블록 공략이 시즌의 약점 국면이었음. tactic_observations scope=possession.]','FINAL (data-only) — 실측·분석 기반 확정. 게임 내 검증은 수동 플레이 환경이라 생략 (사용자 결정 2026-07-05). 이전 게이트: MEDIUM — 게임 미검증, PPDA 실측 기반 | 점유-결과 실측으로 필요성 HIGH, 설정값 자체는 게임 검증 대상.');
INSERT INTO team_tactic_setups VALUES(5,'2025-26','FC26','optimal:lead','4-2-3-1 Wide','Short Passing','Deep',45,NULL,'리드 관리(후반 잠그기): 4-4-2 콤팩트 블록으로 템포 죽이기, 숏패싱 유지. 문서 §1 흡수. rest-defense(풀백 한 번에 한 명만 전진)가 역습 실점 0의 핵심.','FINAL (data-only) — 실측·분석 기반 확정. 게임 내 검증은 수동 플레이 환경이라 생략 (사용자 결정 2026-07-05). 이전 게이트: MEDIUM — 게임 미검증');
INSERT INTO team_tactic_setups VALUES(6,'2026-27','FC26','projected','4-2-3-1 Wide','Short Passing','Balanced',52,NULL,'26/27 예상 XI (2026-07-22 이적 전망 기준): 마르티네스 gk_ballplaying/Build-Up — 캐시 fb_wingback/Balanced·콘사 cb_bpd/Aggressive·파우 토레스 cb_bpd/Build-Up·에스투피냔 fb_att_wb/Support — 고메스(LDM) dm_holding/Ball-Winning·카마라(RDM) dm_holding/Ball-Winning — 맥긴(RM) wm_widemid/Support·만잠비(CAM) cam_halfwinger/Balanced·가르나초(LM) wm_insidefwd/Attack — 왓킨스 st_advanced/Versatile. 팀 설정은 25/26 optimal 셸 유지(파운데이션-퍼스트, obs#6). 근거: 기존 7인=player_role_map optimal 처방, 영입 4인=transfer_targets 실측(에스투피냔 .946/가르나초 .911/만잠비 CAM .817/고메스 LDM .797). 피봇 좌우: 카마라 우중앙 앵커(duties#12)+고메스 좌측 우세 실측(.797 vs 우측 .638). 구조 판정: 더블 볼위닝 피봇→딥 창조 공백(보상: 파우 스텝업·만잠비 LDM 강하 dm_dlp .812·왓킨스 드롭), 좌측=공격 사이드(에스투피냔 오버랩+가르나초 인버티드), 캐비앗: 만잠비 halfwinger CAM-LM 충돌 0.72(가르나초 겹침)·시즌 초 실측 확인 항목. 변형 프리셋 후보: 만잠비 LDM+부엔디아 10번(잠긴 경기), 접전용 가르나초→Balanced형 스왑. 상세: reports/transfer-watch/2026-07-22.md [2026-07-29 우측 브리프 반영] RM 맥긴 wm_widemid/Support는 "디아비 이후 결손"을 균형자로 메운 상태이며 에메리의 실제 요구(뒷공간 침투 빠른 우측 윙어, Tanswell 1티어)와 다르다 — 영입 성사 시 이 슬롯이 최우선 교체 대상. 자금은 유출 선행 조건(SCR/합의금, 베일리→헐이 공간 창출 1순위).','PROJECTED — 이적 미확정 포함(가르나초 MEDIUM-HIGH·에스투피냔 HIGH, 나머지 CONFIRMED/보유). 26/27 실측 축적 후 measured/optimal로 대체 예정. 만잠비·고메스·에스투피냔·가르나초 처방은 타클럽/대표팀 실측 기반이라 빌라 컨텍스트 재검증 필요.');
INSERT INTO team_tactic_setups VALUES(7,'2026-27','FC26','projected:2up-4222','4-2-2-2','Short Passing','Balanced',52,'','왓킨스+잭슨 투톱 예측(실측 아님). 26/27 projected 셸 유지 + 2번째 스트라이커 수용. 포메이션 근거: 빌라 포메이션 상수(4-2-3-1 41/45)의 투톱 예외가 4-2-2-2 ×1(번리 H)·4-4-2 ×3(본머스H·리즈A·첼시A) — 더블 피봇(고메스·카마라 dm_holding)을 보존하려면 4-2-2-2, 두 줄 4 뱅크/리드관리엔 4-4-2. 역할 스태거(핵심): 왓킨스 st_advanced/Attack(최전방 박스 피니셔+좌채널 배후, measured x41 좌편향·xg1.33·xa.03) / 잭슨 st_advanced/Support(하강 링크·양채널·전방압박, transfer_targets id123 실측 fit .752·x48). 2선=가르나초 wm_insidefwd/Attack(좌 내향)+만잠비 cam_halfwinger/Balanced(중앙 공급 — 로저스는 첼시 매각 £117m, 2026-07-25 정정). 폭=풀백 전담(에메리 한 번에 한 명, 캐시 Balanced rest-defense/에스투피냔 Support), 배후 리스크는 파우 스텝업+마르티네스 스위퍼로 상쇄. 수비 국면은 4-4-2 미드블록으로 회귀(기존 셸 정합). 툴 에메리구조 87(vs 4-2-3-1 예상 93)=구조 이탈 정량화. 대안 프리셋: 4-4-2(맥긴 RM·가르나초 LM wm_widemid/Support + 카마라·로저스 중앙 페어).','QUALITATIVE — 예측(what-if) 세팅. 포메이션 상수 예외·에메리 커리어 4-4-2 DNA·잭슨 실측 st_advanced/Support(.752)·왓킨스 measured st_advanced에 근거. 리스크: 두 스트라이커 동시 드롭 시 박스 공동화, 무윙어 폭 부재. 시즌 실측으로 검증 예정.');
INSERT INTO team_tactic_setups VALUES(8,'2026-27','FC26','reference:chelsea-alonso','5-4-1','Short Passing','High',64,'','알론소 레버쿠젠 블루프린트의 첼시 이식(참조 구현, 실측 아님). 부임 2026-05-17 발표·07-01 4년(첼시 공식/ESPN). 개념 골격: 3-4-2-1 스캐폴드 → 공격 3-2-5(5채널 오버로드)·수비 백5. ★FC26 슬롯 제약으로 인게임 포메이션은 5-4-1 채택: 3-4-2-1은 와이드=WM(윙백 역할 선택 불가)·중앙 2미들=CM이라 그리말도/프림퐁 윙백 역할 재현 불가 → 백5(FB 슬롯, fb_inverted/fb_att_wb 사용 가능)+4미드+1톱인 5-4-1이 정확 매핑(수비 국면 백5와도 일치, 공격 3-2-5 전개는 역할 커널 담당). 택티컬 비전=포제션(구 티키타카 — 볼 통제·중앙 지향 빌드업 정합; High Pressing 비전은 다이렉트 지향이라 부적합, 카운터프레스는 수비접근 High+라인 64로 구현). XI(스쿼드 2026-07-25 — 로저스£117m·팔레스트라£43m·퀜다£40m·에메가£22m IN / 쿠쿠레야·A.산투스·T.조지·가르나초(빌라 임대) OUT): 산체스 gk_ballplaying/Build-Up — 콜윌(LCB) cb_bpd/Aggressive(인카피에: 좌 전진 스텝) · 아다라비오요(CB) cb_bpd/Build-Up(타: 중앙 지휘·롱 대각) · 포파나(RCB) cb_wideback/Support(탑소바/코수누: 빌드업 시 와이드 이탈+볼캐리) — 아토(LWB) fb_inverted/Build-Up(그리말도: 딥→대각 내향 플레이메이커) · 팔레스트라(RWB) fb_att_wb/Attack(프림퐁: 터치라인 하이 윙어) — 엔소(LCM) cm_dlp/Build-Up(샤카 오케스트레이터) · 카이세도(RCM) cm_holding/Ball-Winning(팔라시오스 볼위너) — 로저스(LM) wm_wideplm/Attack(비르츠: 좌 하프스페이스 창조 — 빌라 실측 roaming 창조성 승계) · 팔머(RM) wm_insidefwd/Attack(호프만: 우 하프스페이스 득점 커넥터) — 주앙 페드루(ST) st_advanced/Support(보니페이스: 드롭 링크+카운터프레스 선봉). 비대칭 윙백=시스템 축(그리말도 yin/프림퐁 yang). 구조 리스크: 쿠쿠레야 매각으로 그리말도 롤 적임자 아토뿐(백3 좌측 겸직 불가), 중앙 상실 시 취약(레버쿠젠 동일). 로테이션: 제임스 RWB/RCB·에스테방/퀜다 RM·RWB·라비아/에수구 피봇·델랍/에메가 st_target·지튼스 LM·잭슨(빌라行 HIGH, XI 제외). 에메리 빌라(4-2-3-1 Balanced/52)와 대비: 5-4-1 High/64. 툴 프리셋 첼시 26/27 (알론소)와 계약.','QUALITATIVE — 블루프린트 이식(첼시 실전 실측 아님). 레버쿠젠 전술은 themastermindsite·ac3lab·soccertutor·managingmadrid·bulinews 교차(2026-07-25 수집), 스쿼드는 Wikipedia 2026-27 Chelsea season + 첼시 공식 이적 페이지, FC26 슬롯 제약·비전 목록은 EA 커뮤니티 가이드(dexerto/beebom) 확인. 알론소가 첼시에서 레버쿠젠 골격을 그대로 쓸지는 미확인 — 시즌 개막 후 실측 검증 예정.');
INSERT INTO team_tactic_setups VALUES(9,'2026-27','FC26','projected:left-release-A','4-2-3-1 Wide','Short Passing','Balanced',52,NULL,'좌측 해방(가르나초) 모드 설계안 — projected 셸에서 2슬롯 델타. ①CAM cam_playmaker/Roaming (projected의 만잠비 halfwinger 대체): 로저스 INTERPLAY 근거 — CAM halfwinger는 10번 포켓 질량 6.2→4.6 하락 + CAM-LM 충돌 0.45→0.72, 가르나초 wm_insidefwd/Attack 컷인 레인과 정면 충돌. playmaker/Roaming으로 포켓 보호. 캐비앗: 만잠비 CAM 실측최적은 halfwinger 0.817이라 긴장 — 바투리나(CAM 실측형, MEDIUM-HIGH) 영입이 완성 조건. ②LDM 고메스 dm_dlp/Roaming: 좌측 창작 소멸 시 후방 공급 필수(Package G 논리, 커버리지 21/25 복구). 캐비앗: 고메스 기능축=볼위너(obs#32) — 팔리냐(HIGH) 합류 시 팔리냐 RDM holding + 고메스 LDM dlp 분담이 정합. 나머지 셸 동일: 가르나초 LM insidefwd/Attack(.911, 수비복귀 완화 — 래시포드 선례 obs#36 자기진영 .145), LB 마첸 fb_att_wb/Support(디뉴 PSG行; 에스투피냔 영입 시 교체, 컷인 릴레이 겹침 .707 최저=상보), RM 맥긴 wm_widemid/Support 비협상(obs#27 두줄4 — 해방 윙어는 한 번에 한 명), 왓킨스 st_advanced/Versatile 우채널 우선. 용도: 기본 전술 + 강팀 Deep/43-45 모듈레이션(obs#8)에서 최대치 — 강팀전엔 가르나초 전방 F형 스왑(래시포드 강팀 4/5경기 전방 기용 선례). [2026-07-29 고메스 재검증 반영] LDM dm_dlp/Roaming을 고메스에게 처방하는 것은 기능 모순 확정(창조 전무 kp .3·xA .04, holding 재확정) — 이 프리셋의 후방 공급 요건은 진성 DLP형 영입(사라·베르그발·바투리나급) 전제이거나 고메스는 dm_boxcrasher/Balanced(.701, 숙련 보유) 절충으로 대체. [2026-07-29 우측 브리프 반영] Tanswell 1티어 브리프(뒷공간 침투 빠른 우측 윙어, 확정 관심 5명)로 RM 보강이 예정된 슬롯임이 확인 — 단 이 프리셋은 좌측이 해방 사이드라 신규 우측 윙어도 wm_widemid/Support로 강제(좌우 동시 해방 = obs#27 두 줄 4 붕괴). 즉 우측 영입의 Attack 가용은 B1 전용. 목표 커널은 wm_insidefwd이며 wm_winger 아님(디아비 실측 winger .577 < insidefwd .789).','DRAFT — 세션 설계 2026-07-29, 26/27 실측 전. 검증: 시즌 개막 후 가르나초·만잠비 히트맵 수집');
INSERT INTO team_tactic_setups VALUES(10,'2026-27','FC26','projected:interior-left-B1','4-2-3-1 Wide','Short Passing','Balanced',52,NULL,'인테리어 좌측 모드 B1 — 부엔디아 딥 창작형. LM 부엔디아 wm_wideplm/Build-Up (role:LM 재적합 0.782; 좌8 실측 8선발 평점 7.09, 뉴캐슬전 "투웨이+박스 도착", 자기진영 점유 .277=래시포드의 2배 — 완전 뱅크 복귀형) + CAM 만잠비 cam_halfwinger/Balanced (실측최적 0.817 그대로 채택 가능 — Package G 커널 정합: LM wideplm/Build-Up이 측면 충돌 0.72→0.36 복구). 피벗은 projected의 더블 홀딩(고메스+카마라 dm_holding) 유지 가능 — 부엔디아가 딥 공급을 겸하므로 LDM dlp 불요, 고메스 기능축(볼위너, obs#32)과도 정합. LB 마첸 fb_att_wb/Support 임무 격상(좌측 폭 유일 공급원 — 디뉴 시즌 실측 .911 구조 재현). RM 재량 발생(좌측 뱅크 복귀 온전 — 25/26 산초 인버티드 실험이 전부 이 조건에서 나옴): 맥긴 Support 기본 + 알리송 로테이션 허용. 용도: 점유 주도/딥블록 상대 + 약팀 High/67 모듈레이션(obs#8). 에메리 모듈레이션 축1("10번의 정체: 로저스 vs 부엔디아 vs 틸레만스")의 부엔디아 항 상설화. [2026-07-29 사용자 확정 — RM 변경] 맥긴 wm_widemid/Support → wm_wideplm/Attack 기본 채택 (role:season 실측최적 .761 + 기능축 17.1m 중거리 12골=딥블록 킬러 + B1 좌측 뱅크 복귀 온전으로 해방 총량 1명 유지). 세트 조건: ①우측 폭 소멸 → 캐시 오버랩 모듈레이션(축4)과 병행, 마첸 전진 절제 ②FC26 wideplm 숙련 미보유(숙련=widemid) — 인게임 페널티 확인 필요, 확인 전까지 widemid/Support가 폴백. [2026-07-29 우측 브리프 반영 — 업그레이드 경로] 이 프리셋의 해방 우측 슬롯이 Tanswell 브리프의 착지점이다. 맥긴 wm_wideplm/Attack은 잠정치 — 침투 서명이 전방 0.49·자기진영 0.23으로 균형자형이라 브리프의 "뒷공간 반복 침투"를 충족하지 못한다. 영입 성사 시 하지무사 wm_insidefwd/Attack(.923, 전방 0.76·자기진영 0.14)로 교체가 정합 최상이며, 그 경우 맥긴은 RDM 딥롤(7.87) 또는 로테이션으로 이동. 로우·아데예미는 실측 PENDING이라 후순위 판단 보류.','DRAFT — 세션 설계 2026-07-29, 26/27 실측 전. 부엔디아 25/26 실측은 완비, 조합 검증만 남음');
INSERT INTO team_tactic_setups VALUES(11,'2026-27','FC26','projected:interior-left-B2','4-2-3-1 Wide','Short Passing','Balanced',52,NULL,'인테리어 좌측 모드 B2 — 인사이드포워드형(로저스 직무 승계 트랙). LM 만잠비 wm_insidefwd/Balanced (0.700, 중앙 회귀 성향 — 로테이션 등급) + CAM cam_playmaker/Roaming (포켓 질량 6.2, 창작+도착 분담 구조 — B1의 더블 창작과 구별). 장기 1옵션: 헤밍스 — 에메리가 left 10 프로젝션(Tanswell/The Athletic 2026-07), 박스투박스→인테리어 전환은 램지 개발 경로 재현, 단 1군 실측 표본 부재로 PENDING(45분+ 출전 축적 시 히트맵 수집). 가르나초 Balanced 하향 기용은 실측(Attack 0.911) 미스핏이라 비권장 — B2의 LM은 만잠비/헤밍스 전용, 가르나초 선발이면 left-release-A 사용. 나머지 슬롯 B1과 동일(더블 홀딩, LB 마첸 폭 전담, RM 재량). 용도: B1과 같은 점유 국면이나 부엔디아 부재/세대교체 이후의 대안.','DRAFT — 세션 설계 2026-07-29. LM 후보(만잠비 LM 0.700 로테이션급, 헤밍스 실측 無)라 3안 중 최저 우선순위');
